// =============================================================================
//  (th4) GERMAN localization (LANG_DE). Mirrors LocalizationFR.cpp structure.
//
//  ENCODING: raw CP1252 bytes (latin-1 on disk). German umlauts/eszett are real
//  bytes (ä=E4, ö=F6, ü=FC, ß=DF, Ä=C4, Ö=D6, Ü=DC); the PT/FR CEL font pack
//  (TH4loc_prt.mor) carries the glyphs, mounted for LANG_DE in Windows.cpp.
//
//  ---- STATUS -------------------------------------------------------------
//  Batch 1: Menu, Spell, SpellNom, Warp, Element, Spicies, OnScreen, Quest.
//  All other tables hold a lone placeholder => 0 rows => English fallback.
//  Dedicated DE_* functions (traits/GC/monster names) come in later batches.
//  Keys must byte-exactly match the English source literal.
// =============================================================================

struct UiStr  { const char* en; const char* de; }; // .de column holds the DE text
struct IdxStr { int index; const char* tr; };

