// -----------------------------------------------------------------------------
static bool isPlaceholder( const UiStr&  r ) { return r.en == 0; }
static bool isPlaceholder( const IdxStr& r ) { return r.index < 0 && r.tr == 0; }

template<typename T, size_t N>
static int countRows( const T (&arr)[N] )
{
	if( N == 1 && isPlaceholder( arr[0] ) ) return 0;
	return (int)N;
}

const UiStr* DE_GetStrTable( int ovlId, int* n )
{
	switch( ovlId ){
		case OVL_UI:            *n = countRows(DE_Ui);           return DE_Ui;
		case OVL_MENU:          *n = countRows(DE_Menu);         return DE_Menu;
		case OVL_UNIQUE_ITEM:   *n = countRows(DE_UniqueItem);   return DE_UniqueItem;
		case OVL_AFFIX_PREFIX:  *n = countRows(DE_AffixPrefix);  return DE_AffixPrefix;
		case OVL_AFFIX_SUFFIX:  *n = countRows(DE_AffixSuffix);  return DE_AffixSuffix;
		case OVL_BASE_ITEM:     *n = countRows(DE_BaseItem);     return DE_BaseItem;
		case OVL_BASE_NAME2:    *n = countRows(DE_BaseName2);    return DE_BaseName2;
		case OVL_ELEMENT:       *n = countRows(DE_Element);      return DE_Element;
		case OVL_SPICIES:       *n = countRows(DE_Spicies);      return DE_Spicies;
		case OVL_ICEAGE:        *n = countRows(DE_IceAge);       return DE_IceAge;
		case OVL_SPELL:         *n = countRows(DE_Spell);        return DE_Spell;
		case OVL_SPELL_NOM:     *n = countRows(DE_SpellNom);     return DE_SpellNom;
		case OVL_PERK_NAME:     *n = countRows(DE_PerkName);     return DE_PerkName;
		case OVL_PERK_DESC:     *n = countRows(DE_PerkDesc);     return DE_PerkDesc;
		case OVL_WARP:          *n = countRows(DE_Warp);         return DE_Warp;
	}
	*n = 0; return 0;
}

const IdxStr* DE_GetIdxTable( int ovlId, int* n )
{
	switch( ovlId ){
		case OVL_SPEECH:    *n = countRows(DE_Speech);     return DE_Speech;
		case OVL_ONSCREEN:  *n = countRows(DE_OnScreen);   return DE_OnScreen;
		case OVL_QUEST:     *n = countRows(DE_Quest);      return DE_Quest;
	}
	*n = 0; return 0;
}

