const char* DE_GCInfoDesc( int gc )
{
	switch( gc ){
		case 0: return "Spielregeln sind optional. Sie bleiben dem Charakter für immer erhalten. Sie können bestimmte Perks und Synergien hinzufügen oder entfernen.";
		case 1: return "Autospeichern erspart das manuelle Speichern; das Spiel wird automatisch gespeichert, wie im Mehrspielermodus.";
		case 2: return "Im Kampf können Gegenstände weder an- noch abgelegt werden (außer Handplätze).";
		case 3: return "Beim Tod lässt du angelegte Gegenstände fallen. Warnung: Werden sie nicht in derselben Sitzung geborgen, verschwinden sie.";
		case 4: return "Macht das Spiel leichter. Monster fügen dir nur halben Schaden zu. Leichter geht es nicht.";
		case 5: return "Die Städter verkaufen dir keine Gegenstände. Ihre Dienste bieten sie jedoch an: Reparieren, Identifizieren, Verzaubern usw.";
		case 6: return "Macht das Spiel schwerer. Monster fügen doppelten Schaden zu. Härter wird es nicht.";
		case 7: return "Monster lassen keine Attribut-Elixiere mehr zufällig fallen. Hinweis: Der Perk Starker Trinker gibt weiterhin Elixiere von einzigartigen Monstern.";
		case 8: return "Macht das Spiel leichter. Monster mit Fernangriffen weichen nicht zurück.";
		case 9: return "Blutdürstig dringst du tief in das Labyrinth von Tristram vor, um die Schwachen zu jagen. Dies ändert das Spiel: Du nutzt keine Gegenstände und verlässt dich auf deine angeborenen Kräfte.";
		case 10: return "Macht das Spiel leichter. Der Waffentyp muss nicht mehr an den Monstertyp angepasst werden. Alle Waffen machen neutralen Schaden. Einfach drauflos.";
		case 11: return "Macht das Spiel leichter. Monster verlieren Immunitäten, Zauberwechsel entfallen. Steinfluch, Knochengeist, Elementar- und heilige Zauber bleiben unberührt.";
		case 12: return "Macht das Spiel leichter. Furor hat keine Abklingzeit und kann sofort erneut gewirkt werden.";
		case 13: return "Erhöht die Herausforderung. Der Charakter hat keine Grundregeneration von Leben und Mana.";
		case 14: return "Erhöht die Herausforderung. Monster lassen keine anlegbaren Gegenstände fallen. Diese sind durch Kauf und/oder Verzauberung zu beschaffen.";
		case 15: return "Kosmetische Änderung. Die Verliese wirken wie im tiefsten Winter, alles ist vereist und gefroren. Hast du dir je vorgestellt, wie eine zugefrorene Hölle aussähe?";
		case 16: return "Ändert die Spielweise. Es wird stets dasselbe Verlies mit denselben Monstern erzeugt. Du kannst dein Timing mit jedem Durchlauf verbessern.";
		case 17: return "Macht das Spiel schwerer. Monster haben +200% Trefferpunkte.";
		case 18: return "Macht das Spiel leichter. Gegenstände werden bei Haltbarkeit null nicht zerstört, sondern nur unbrauchbar, bis sie repariert sind.";
		case 19: return "Erhöht die Herausforderung. Die Automap ist nicht verfügbar. Du musst dich ohne sie zurechtfinden. Schon verlaufen?";
		case 20: return "Macht das Spiel leichter. Deine Angriffe fügen Monstern doppelten Schaden zu. Warnung: Es kann enttäuschend leicht werden. Nicht wählen, wenn du den Nervenkitzel behalten willst.";
		case 21: return "Erhöht die Herausforderung. Sehen hebt Monster im Dunkeln nicht hervor.";
		case 22: return "Du bist infiziert. Die Seuche des Schwarzen Todes hat dich befallen. Ein Fluch, der sich unaufhaltsam entwickelt. Wie lange hältst du durch, bis er dein Leben fordert?";
		case 23: return "Du hast Pech. Startattribute = 5. Nur 2 Attributpunkte pro Stufenaufstieg. -75% auf MF/GF/EP. Keine Perks für EP, Elixiere, Magie finden und Stufen-Attribute.";
		case 24: return "Klassische Diablo-Ironman-Bedingungen: kein Bonus auf EP, MF, Attribute. Keine Öle und IDs von Bossen.";
		case 25: return "Macht das Spiel leichter. Erfahrung ist verdoppelt. Warnung: Dies ist nicht das vorgesehene Spieltempo. Nur zum Testen verwenden.";
		case 26: return "Das Spiel wird automatisch gespeichert. In der Stadt gibt es keine Wiederbelebung (neues Spiel nötig), und alle fallengelassenen Gegenstände gehen beim Tod verloren. Ein Hardcore-Modus für Gegenstände.";
		case 27: return "Du bist eine Infiltrationseinheit, Modell 101. In die Vergangenheit gesandt, um Monster auszurotten. Sie werden einem Bösen begegnen, das ihr Begreifen übersteigt...";
		case 28: return "Du schleppst Waffen, die einen normalen Mann entzweibrechen würden. Dinge, die es in dieser Welt nicht geben dürfte. Drück ab - die Salve reißt alles nieder.";
		case 29: return "Soldat der Enklave-Streitkräfte, ausgebildet zur Vernichtung von Mutanten und genetischer Unreinheit. Gestrandet in einer Welt, die nie nukleares Feuer kannte.";
	}
	return 0;
}
